class Solution:
    def findSubstringInWraproundString(self, p: str) -> int:
        i = 0
        n = len(p)
        map_ = collections.defaultdict(int)
        while i<n:
            start = i
            prev_val = p[i]
            while i+1<n and get_next(prev_val) == p[i+1]:
                prev_val = p[i+1]
                i+=1
            while start <= i:
                curr_val = i-start+1
                map_[p[start]] = max(map_[p[start]], curr_val)
                start += 1
            i+=1
        return sum(map_.values())

class Solution:
    def findSubstringInWraproundString(self, p: str) -> int:
        letters = [0] * 26
        result, length = 0, 0
        for i in range(len(p)):
            curr = ord(p[i]) - ord('a')
            if i > 0 and ord(p[i-1]) != (curr-1)%26 + ord('a'):
                length = 0
            length += 1
            if length > letters[curr]:
                result += length - letters[curr]
                letters[curr] = length
        return result

