    def findComplement(self, num: int) -> int:
        i = 0
        while(2**i <= num):
            i += 1
        return (2**i - num - 1)

class Solution:
    def findComplement(self, num: int) -> int:
        i = 1
        while i <= num:
            i <<= 1
        return (i - 1) ^ num

class Solution:
    def findComplement(self, num: int) -> int:
        bits = '{0:b}'.format(num)
        complement_bits = ''.join('1' if bit == '0' else '0' for bit in bits)
        return int(complement_bits, 2)
